const listRecoverablePositionCashOutKeys = `-- name: ListRecoverablePositionCashOutKeys :many
SELECT id
FROM worm_position_cash_outs
WHERE (
    state = 'QUEUED'
    OR (
      state IN ('PREFLIGHTING', 'CLOSING')
      AND (claim_id IS NULL OR claim_expires_at <= $1::timestamptz)
    )
    OR (
      state = 'AWAITING_COMPLETION'
      AND next_poll_at <= $1::timestamptz
      AND (claim_id IS NULL OR claim_expires_at <= $1::timestamptz)
    )
    OR (
      state = 'RECONCILIATION_REQUIRED'
      AND next_poll_at <= $1::timestamptz
      AND (claim_id IS NULL OR claim_expires_at <= $1::timestamptz)
    )
  )
ORDER BY COALESCE(next_poll_at, updated_at), created_at, id
LIMIT $2::integer
`

