const resolvePositionCashOutAttempt = `-- name: ResolvePositionCashOutAttempt :one
UPDATE worm_position_cash_out_attempts
SET state = $1::text,
    http_status = $2::integer,
    provider_code = $3::integer,
    provider_slug = $4::text,
    provider_state = $5::text,
    error_code = $6::text,
    completed_at = $7::timestamptz,
    updated_at = $7::timestamptz
WHERE id = $8::uuid
  AND cash_out_id = $9::uuid
  AND state = 'DISPATCHED'
  AND $1::text IN ('ACKNOWLEDGED', 'REJECTED', 'OUTCOME_UNKNOWN')
RETURNING id, cash_out_id, state, request_sha256, http_status, provider_code, provider_slug, provider_state, error_code, prepared_at, dispatched_at, completed_at, created_at, updated_at
`

type ResolvePositionCashOutAttemptParams struct {
	State         string
	HttpStatus    pgtype.Int4
	ProviderCode  pgtype.Int4
	ProviderSlug  string
	ProviderState string
	ErrorCode     string
	Now           pgtype.Timestamptz
	ID            pgtype.UUID
	CashOutID     pgtype.UUID
}

func (q *Queries) ResolvePositionCashOutAttempt(ctx context.Context, arg ResolvePositionCashOutAttemptParams) (WormPositionCashOutAttempt, error) {
	row := q.db.QueryRow(ctx, resolvePositionCashOutAttempt,
		arg.State,
		arg.HttpStatus,
		arg.ProviderCode,
		arg.ProviderSlug,
		arg.ProviderState,
		arg.ErrorCode,
		arg.Now,
		arg.ID,
		arg.CashOutID,
	)
	var i WormPositionCashOutAttempt
	err := row.Scan(
		&i.ID,
		&i.CashOutID,
		&i.State,
		&i.RequestSha256,
		&i.HttpStatus,
		&i.ProviderCode,
		&i.ProviderSlug,
		&i.ProviderState,
		&i.ErrorCode,
		&i.PreparedAt,
		&i.DispatchedAt,
		&i.CompletedAt,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

const touchPositionCashOutAfterDispatch = `-- name: TouchPositionCashOutAfterDispatch :execrows
UPDATE worm_position_cash_outs
SET revision = revision + 1, updated_at = $1::timestamptz
WHERE id = $2::uuid
  AND state = 'CLOSING'
  AND claim_id = $3::uuid
`

type TouchPositionCashOutAfterDispatchParams struct {
	Now     pgtype.Timestamptz
	ID      pgtype.UUID
	ClaimID pgtype.UUID
}

func (q *Queries) TouchPositionCashOutAfterDispatch(ctx context.Context, arg TouchPositionCashOutAfterDispatchParams) (int64, error) {
	result, err := q.db.Exec(ctx, touchPositionCashOutAfterDispatch, arg.Now, arg.ID, arg.ClaimID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
